(ns armstrong-numbers) (defn exp [base exp-count] (reduce * (repeat exp-count base))) (defn to-int-and-exp [exponent str-int] (exp (Integer/parseInt str-int) exponent)) (defn get-sum [str-seq] (def cnt (count str-seq)) (def partial-int-exp (partial to-int-and-exp cnt)) (def str-seq-split (map str (sequence str-seq))) (reduce + (map partial-int-exp str-seq-split))) (defn armstrong? [num-in] (def str-seq (str num-in)) (if (= num-in (get-sum str-seq)) true false ) )
